defmodule Medoru.Content.KanjiRadicals do
  @moduledoc """
  Hardcoded lookup table for the 214 traditional kanji radicals plus
  variant forms used in the `kanji.radicals` array.

  Each radical entry contains:
    - `:character` — the canonical radical form
    - `:meaning` — English meaning(s)
    - `:variants` — alternate shapes (e.g. 氵 for 水)
    - `:category` — rough thematic group
    - `:stroke_count` — stroke count of the radical

  Use `get/1` to look up by any radical symbol (main or variant).
  """

  defstruct [:character, :meaning, :variants, :category, :stroke_count]

  @categories %{
    strokes: "Strokes",
    nature: "Nature",
    people: "People & Body",
    society: "Society",
    plants: "Plants & Agriculture",
    animals: "Animals",
    food: "Food",
    home: "Home & Objects",
    clothing: "Clothing",
    color: "Color",
    weapons: "Weapons & Tools",
    numbers: "Numbers",
    abstract: "Abstract"
  }

