  # Build lookup maps at compile time
  @by_character Map.new(@radicals, fn r -> {r.character, r} end)

  @by_variant @radicals
              |> Enum.flat_map(fn r ->
                Enum.map(r.variants, fn v -> {v, r} end)
              end)
              |> Map.new()

  @all @radicals

  @doc """
  Returns the list of all 214 canonical radicals.
  """
  def all, do: @all

  @doc """
  Looks up a radical by its canonical character or any variant form.

  ## Examples

      iex> KanjiRadicals.get("水")
      %{character: "水", meaning: "water", variants: ["氵", "氺"], ...}

      iex> KanjiRadicals.get("氵")
      %{character: "水", meaning: "water", variants: ["氵", "氺"], ...}

      iex> KanjiRadicals.get("xxx")
      nil

  """
  def get(character) when is_binary(character) do
    Map.get(@by_character, character) || Map.get(@by_variant, character)
  end

  @doc """
  Returns the meaning for a radical character, or nil if unknown.
  """
  def meaning(character) when is_binary(character) do
    case get(character) do
      nil -> nil
      radical -> radical.meaning
    end
  end

  @doc """
  Returns true if the given character is a known radical (main or variant).
  """
  def radical?(character) when is_binary(character) do
    get(character) != nil
  end

  def radical?(nil), do: false

  @doc """
  Returns all radicals in a given category.
  """
  def by_category(category) when is_atom(category) do
    Enum.filter(@all, &(&1.category == category))
  end

  @doc """
  Returns the human-readable category name.
  """
  def category_name(category) when is_atom(category) do
    Map.get(@categories, category, "Unknown")
  end

  @doc """
  Returns a map of category => [radicals].
  """
  def grouped_by_category do
    @all
    |> Enum.group_by(& &1.category)
    |> Enum.map(fn {cat, radicals} -> {cat, Enum.sort_by(radicals, & &1.stroke_count)} end)
    |> Enum.into(%{})
  end

