  @doc """
  Returns the number of kanji that contain this radical.
  """
  def frequency(character) when is_binary(character) do
    case Map.get(@frequency_and_kanji, character) do
      nil -> 0
      {freq, _} -> freq
    end
  end

  @doc """
  Returns the top kanji containing this radical, as a list of
  %{character: ..., id: ..., frequency: ...} maps.
  Max 10, may be fewer.
  """
  def top_kanji(character) when is_binary(character) do
    case Map.get(@frequency_and_kanji, character) do
      nil ->
        []

      {_, kanji_list} ->
        Enum.map(kanji_list, fn {char, id, freq} ->
          %{character: char, id: id, frequency: freq}
        end)
    end
  end

  @doc """
  Returns all radicals sorted by frequency (most common first).
  """
  def by_frequency do
    @frequency_and_kanji
    |> Enum.reject(fn {char, _} -> char == "" end)
    |> Enum.map(fn {char, {freq, _}} ->
      radical = get(char)

      %{
        character: char,
        meaning: radical && radical.meaning,
        frequency: freq,
        stroke_count: radical && radical.stroke_count,
        category: radical && radical.category
      }
    end)
    |> Enum.sort_by(& &1.frequency, :desc)
  end
end
